package io.knowledgebrain.learning;
import java.util.*;import java.io.IOException;import jakarta.servlet.http.HttpServletRequest;import org.springframework.web.bind.annotation.*;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.beans.factory.annotation.Value;import org.springframework.http.*;import org.springframework.web.server.ResponseStatusException;import io.micrometer.core.instrument.MeterRegistry;
@RestController
@ConditionalOnProperty(name="brain.learning.api.enabled",havingValue="true")
@RequestMapping("/api/groups/{groupId}/courses/{courseId}/my-progress")
final class CourseProgressController {
 record View(CourseContextClient.Reference context,CourseProgressStore.Progress progress,boolean canWrite) {}
 private final CourseProgressStore store;private final CourseContextClient context;private final RoadmapController body;private final MeterRegistry metrics;private final String origin;
 CourseProgressController(CourseProgressStore store,CourseContextClient context,RoadmapController body,MeterRegistry metrics,@Value("${brain.learning.browser-origin}")String origin){this.store=store;this.context=context;this.body=body;this.metrics=metrics;this.origin=origin;}
 private CourseContextClient.Reference access(UUID group,UUID course,HttpServletRequest r,boolean write,String trace){if(!r.isSecure())throw RoadmapGraph.bad();if(write&&(Collections.list(r.getHeaders("Origin")).size()!=1||!origin.equals(r.getHeader("Origin"))||r.getHeader("Sec-Fetch-Site")!=null&&!r.getHeader("Sec-Fetch-Site").equals("same-origin")))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Same-origin request required");var tokens=new ArrayList<String>();for(var header:Collections.list(r.getHeaders("Cookie")))for(var part:header.split(";")){var pair=part.strip().split("=",2);if(pair.length==2&&pair[0].equals("__Host-brain_guest"))tokens.add(pair[1]);}if(tokens.size()!=1||!tokens.getFirst().matches("[A-Za-z0-9_-]{43}"))throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Session required");var ref=context.check(group,course,tokens.getFirst(),trace);if(write&&!ref.writable())throw new ResponseStatusException(HttpStatus.CONFLICT,"Current enrollment and writable Course required");return ref;}
 private void query(HttpServletRequest r,Set<String> allowed){if(r.getQueryString()!=null&&r.getQueryString().length()>256)throw RoadmapGraph.bad();RoadmapController.parameters(r,allowed);}
 static String tag(long version){return "\"cp"+version+"\"";}
 @GetMapping("/revisions") ResponseEntity<?> history(@PathVariable String groupId,@PathVariable String courseId,HttpServletRequest r){query(r,Set.of("before","limit"));UUID group=RoadmapGraph.id(groupId),course=RoadmapGraph.id(courseId);long before=RoadmapController.number(r.getParameter("before"),Long.MAX_VALUE,Long.MAX_VALUE);int limit=(int)RoadmapController.number(r.getParameter("limit"),5,10);var ref=access(group,course,r,false,RoadmapController.parent(r));metrics.counter("brain.learning.course.progress.reads","type","history").increment();return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(store.history(ref,before,limit));}
 @GetMapping ResponseEntity<?> get(@PathVariable String groupId,@PathVariable String courseId,HttpServletRequest r){query(r,Set.of());UUID group=RoadmapGraph.id(groupId),course=RoadmapGraph.id(courseId);var ref=access(group,course,r,false,RoadmapController.parent(r));var v=store.get(ref);metrics.counter("brain.learning.course.progress.reads","type","current").increment();return ResponseEntity.ok().eTag(tag(v.version())).cacheControl(CacheControl.noStore()).body(new View(ref,v,ref.writable()));}
 @PutMapping("/studies/{studyId}") ResponseEntity<?> change(@PathVariable String groupId,@PathVariable String courseId,@PathVariable String studyId,HttpServletRequest r)throws IOException{query(r,Set.of());UUID group=RoadmapGraph.id(groupId),course=RoadmapGraph.id(courseId),study=RoadmapGraph.id(studyId);String trace=RoadmapController.parent(r);var ref=access(group,course,r,true,trace);long expected=LearningStudyController.version(r,"cp",true);var input=body.body(r,4096);if(input.size()!=3||!input.path("status").isString())throw RoadmapGraph.bad();for(String n:List.of("courseVersion","enrollmentVersion"))if(!input.path(n).isIntegralNumber()||!input.path(n).canConvertToLong()||input.path(n).asLong()<1)throw RoadmapGraph.bad();if(input.path("courseVersion").asLong()!=ref.courseVersion()||input.path("enrollmentVersion").asLong()!=ref.enrollmentVersion())throw new ResponseStatusException(HttpStatus.CONFLICT,"Course or enrollment changed; refresh context");var v=store.change(ref,study,expected,input.path("status").asString(),trace.substring(3,35));metrics.counter("brain.learning.course.progress.changes").increment();org.slf4j.LoggerFactory.getLogger(getClass()).info("course_progress progress_id={} trace_id={}",v.progressId(),trace.substring(3,35));return ResponseEntity.ok().eTag(tag(v.version())).cacheControl(CacheControl.noStore()).body(v);}
}
